import sys
sys.setrecursionlimit(10000)
def f(g):
    h,w=len(g),len(g[0])
    # connected components of 3s (4-conn)
    seen=[[False]*w for _ in range(h)]; boxes=[]
    for y in range(h):
        for x in range(w):
            if g[y][x]==3 and not seen[y][x]:
                st=[(y,x)]; seen[y][x]=True; cells=[]
                while st:
                    cy,cx=st.pop(); cells.append((cy,cx))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=cy+dy,cx+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]==3 and not seen[ny][nx]:
                            seen[ny][nx]=True; st.append((ny,nx))
                ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
                boxes.append((min(ys),max(ys),min(xs),max(xs)))
    o=[r[:] for r in g]
    twos=[(y,x) for y in range(h) for x in range(w) if g[y][x]==2]
    for y,x in twos:
        if any(y0<=y<=y1 and x0<=x<=x1 for y0,y1,x0,x1 in boxes):
            for dy in(-1,0,1):
                for dx in(-1,0,1):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and g[yy][xx]!=2:
                        o[yy][xx]=1
    return o
